insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Delta', 'Any', 'Pet', 'domestic', 'CONNECTIONS', 'Connections: allow extra time; Delta Connection pets need 48h confirmation', 'Delta advises allowing plenty of extra time to change planes with a pet. If transferring from a Delta flight to a Delta Connection flight, the Delta flight must be confirmed at least 48 hours before the Delta Connection departure so transfer arrangements can be made. Check partner airline pet policies separately.', '', NULL, 'https://www.delta.com/content/www/en_US/traveling-with-us/special-travel-needs/pets/pet-travel-options/connection-carriers-and-pet-travel.html', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('American Airlines', 'Any', 'Pet', 'domestic', 'CONNECTIONS', 'Carry-on pets: check each operating carrier; connection fee rule if layover ≥4 hours', 'American does not collect pet fees for other operating airlines on your trip — check in with each airline and pay that airline''s fee. Carry-on pet fees apply again if a stopover or connection is 4 hours or more. For checked pets (military/State Dept only), connections are limited to listed hubs (CLT, ORD, DFW, LAX, JFK, LGA, MIA, PHL, PHX, DCA).', '', NULL, 'https://www.aa.com/i18n/travel-info/special-assistance/pets.jsp', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('United', 'Any', 'Pet', 'domestic', 'CONNECTIONS', 'Connections on partners: confirm each airline''s pet policy; United/United Express OK where destination allows', 'United says you can take pets on flights operated by United or United Express when the destination allows pets. If you travel on multiple airlines or partners, check each airline''s pet policy. International pet adds require a phone call.', '', NULL, 'https://www.united.com/en/us/fly/travel/traveling-with-pets.html', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Southwest', 'Any', 'Pet', 'domestic', 'CONNECTIONS', 'Airline does not publish a dedicated cabin-pet connection rule — call before booking a connecting itinerary', 'Southwest''s published pet pages cover onboard/cabin rules and the 6-carrier limit but do not spell out a separate connection/layover procedure for cabin pets. Call Southwest Reservations before booking a connecting itinerary with a pet to confirm space on every segment.', '', NULL, 'https://support.southwest.com/helpcenter/s/article/pet-policy', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('JetBlue', 'Any', 'Pet', 'domestic', 'CONNECTIONS', 'Airline does not publish a dedicated cabin-pet connection rule — confirm pet on each segment when adding', 'JetBlue''s traveling-with-pets page covers domestic acceptance, carrier size, seats and airport steps but does not publish a separate connection/layover procedure. Add the pet (online or 800-538-2583) for each flight on your itinerary and confirm space before travel.', '', NULL, 'https://www.jetblue.com/help/traveling-with-pets', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Alaska Airlines', 'Any', 'Pet', 'domestic', 'CONNECTIONS', 'Alaska/Hawaiian do not transfer baggage-compartment pets to other carriers; cabin connections — call to confirm', 'Alaska states that if plans include another airline, contact that airline directly for space and fees. Alaska and Hawaiian do not transfer pets traveling in the baggage compartment to other carriers — those pets must be claimed and rechecked. For cabin pets on connecting itineraries, call or chat Alaska to reserve space on each Alaska/Hawaiian segment.', '', NULL, 'https://www.alaskaair.com/content/travel-info/policies/pets-traveling-with-pets', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Frontier', 'Any', 'Pet', 'domestic', 'CONNECTIONS', 'Codeshare/partner flights: check that airline''s pet terms; Frontier cabin pets are domestic-focused', 'Frontier''s family & pets page notes that on codeshare flights you should check the codeshare terms. Frontier does not accept new pets for international travel. Confirm your pet is reserved on each Frontier-operated segment.', '', NULL, 'https://www.flyfrontier.com/travel/travel-info/family-pets', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Allegiant', 'Any', 'Pet', 'domestic', 'CONNECTIONS', 'Allegiant does not publish cabin-pet connection rules — call (702) 505-8888 before a connecting trip', 'Allegiant''s published pet policy covers cabin rules within the contiguous 48 states, fees, seats and 1-hour check-in, but does not describe connection/layover procedures. Allegiant generally operates point-to-point. Call (702) 505-8888 before booking a connecting itinerary with a pet.', '', NULL, 'https://www.allegiantair.com/traveling-with-pets', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Sun Country', 'Any', 'Pet', 'domestic', 'CONNECTIONS', 'Sun Country does not accept pets for interline travel', 'Sun Country''s Contract of Carriage (Rule 200) states Sun Country will not accept pets for interline travel. Cabin pets are not accepted on international flights or flights to/from Anchorage, Hawaii, or Puerto Rico. Book pet space by phone with a Sun Country reservation agent (651-905-2737).', '', NULL, 'https://assets.ctfassets.net/2aov1ouggrmn/6pjlsMvuaBFa9iE7F3qGFF/91b44685006da079165739c0ff850f42/2026-01-27_Contract_of_Carriage.pdf', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Alaska Airlines', 'Any', 'Pet', 'domestic', 'SEAT RESTRICTION', 'Airline does not clearly list cabin seat bans on its main pet pages — confirm when you reserve', 'Alaska''s Fur-st Class Care overview covers booking by chat/phone and fees but does not clearly list exit-row/bulkhead bans for cabin pets on the pages we verified. When you call or chat to reserve your pet, ask the agent which seats are allowed on your aircraft.', '', NULL, 'https://www.alaskaair.com/content/travel-info/policies/pets-traveling-with-pets', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Sun Country', 'Any', 'Pet', 'domestic', 'SEAT RESTRICTION', 'No exit-row or bulkhead seats with a cabin pet', 'Sun Country''s Contract of Carriage requires the pet carrier to remain under the seat in front of you and states seating in an exit row or bulkhead row is not permitted.', '', NULL, 'https://assets.ctfassets.net/2aov1ouggrmn/6pjlsMvuaBFa9iE7F3qGFF/91b44685006da079165739c0ff850f42/2026-01-27_Contract_of_Carriage.pdf', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Frontier', 'Any', 'Pet', 'domestic', 'BREED RESTRICTION', 'No published breed ban for in-cabin pets on Frontier''s pets page', 'Frontier''s published cabin pet rules list allowed species (dogs, cats, rabbits, guinea pigs, hamsters, small household birds on U.S. flights) and banned species (large birds, rodents like mice/rats, ferrets, reptiles, etc.) but do not publish a snub-nose/brachycephalic breed ban for cabin pets.', '', NULL, 'https://www.flyfrontier.com/travel/travel-info/family-pets', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Allegiant', 'Any', 'Pet', 'domestic', 'BREED RESTRICTION', 'No published breed ban — domestic dogs and cats only', 'Allegiant''s pet policy accepts domestic dogs and cats only. It does not publish snub-nose or brachycephalic breed restrictions for cabin pets.', '', NULL, 'https://www.allegiantair.com/traveling-with-pets', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Sun Country', 'Any', 'Pet', 'domestic', 'BREED RESTRICTION', 'No published breed ban for cabin pets — cats and dogs 35 lbs or less', 'Sun Country''s Contract of Carriage accepts small cats and dogs weighing 35 lbs or less in the cabin. It does not list brachycephalic breed exclusions for cabin pets.', '', NULL, 'https://assets.ctfassets.net/2aov1ouggrmn/6pjlsMvuaBFa9iE7F3qGFF/91b44685006da079165739c0ff850f42/2026-01-27_Contract_of_Carriage.pdf', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Sun Country', 'Any', 'Pet', 'domestic', 'PET FEE', 'In-cabin pet fee: non-refundable per segment; higher without advance reservation — call 651-905-2737 for the current dollar amount', 'Sun Country''s Contract of Carriage requires a non-refundable fee per flight segment when a pet reservation is made in advance, and a higher per-segment fee without an advance reservation (space permitting). The Contract of Carriage does not list the dollar amount. Call Sun Country Reservations at 651-905-2737 to confirm the current fee and reserve your pet.', '', NULL, 'https://assets.ctfassets.net/2aov1ouggrmn/6pjlsMvuaBFa9iE7F3qGFF/91b44685006da079165739c0ff850f42/2026-01-27_Contract_of_Carriage.pdf', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Sun Country', 'Any', 'Pet', 'domestic', 'DAY OF FLIGHT', 'Check in early; pet must stay in carrier under the seat; phone booking required', 'Pet reservations can only be made by phone with a Sun Country reservation agent. On travel day the pet must remain in its carrier under the seat continuously from boarding until deplaning. Carrier max 17"L × 12"W × 9"H; soft-sided recommended. Check in early — Sun Country recommends arriving 120 minutes before domestic departure.', '', NULL, 'https://assets.ctfassets.net/2aov1ouggrmn/6pjlsMvuaBFa9iE7F3qGFF/91b44685006da079165739c0ff850f42/2026-01-27_Contract_of_Carriage.pdf', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Frontier', 'Any', 'Pet', 'domestic', 'SEAT RESTRICTION', 'No row one or exit-row seats with a cabin pet', 'Frontier states you may not sit in row one or an exit row when traveling with a pet. The pet must remain in the travel container at all times.', '', NULL, 'https://www.flyfrontier.com/travel/travel-info/family-pets', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Any', 'Any', 'Pet', 'domestic', 'AIRPORT DAY-OF', 'TSA security: remove pet from carrier; never put the pet through the X-ray', 'At the TSA checkpoint, remove your pet from the carrier and place the empty carrier through the X-ray. Keep control of your pet (carry or leash) and remove the leash when carrying the pet through the metal detector. Carriers get a visual and/or physical inspection. Never put your pet through the X-ray machine.', '', NULL, 'https://www.tsa.gov/travel/frequently-asked-questions/can-i-take-my-pet-through-security-checkpoint', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Any', 'Any', 'Pet', 'domestic', 'PACKING', 'What to pack for airport and cabin pet travel', 'Verified traveler/airline guidance commonly includes: collapsible water bowl, leash, absorbent pads or liners for the carrier, familiar blanket or toy, plastic bags, treats for after security, and printed copies of health/vaccine docs when required. Follow your airline''s rule on feeding/watering before departure (several advise limited food/water within a few hours of flight). Do not sedate pets unless a vet specifically directs — AVMA warns altitude risks.', '', NULL, 'https://www.united.com/en/us/fly/travel/traveling-with-pets.html', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Any', 'Any', 'Pet', 'domestic', 'AIRPORT DAY-OF', 'Pet relief areas: use airport maps; you may need to exit security and re-clear', 'Many U.S. airports have designated pet relief areas. Locations vary — check your airport''s official website or airline app maps (United notes its app airport maps). Some relief areas are outside security; if you exit, you and your pet must go through TSA screening again.', '', NULL, 'https://www.united.com/en/us/fly/travel/traveling-with-pets.html', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Aeroméxico', 'Any', 'Pet', 'international', 'PET FEE', 'Cabin pet fee: not listed as a fixed dollar amount on Aeroméxico''s public pets page — confirm when you reserve', 'Aeroméxico''s official pets page requires advance reservation for cabin pets but does not publish a single fixed USD/MXN cabin fee on that page. Confirm the current fee when you reserve the pet service with Aeroméxico before booking.', '', NULL, 'https://www.aeromexico.com/es_mx/vuelos-con-mascotas', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Aeroméxico', 'Any', 'Pet', 'international', 'KENNEL REQUIREMENT', 'Cabin: pet + carrier max 9 kg; rigid or soft carrier', 'Small dogs and cats may travel in cabin in a rigid or soft carrier. Maximum weight is 9 kg including the pet and carrier. Health certificate and vaccination record are required; reserve in advance.', '', NULL, 'https://www.aeromexico.com/es_mx/vuelos-con-mascotas', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Aeroméxico', 'Any', 'Pet', 'international', 'BOOKING REQUIREMENT', 'Reserve pet space in advance with Aeroméxico', 'Aeroméxico requires advance reservation for cabin pets and notes availability is limited. Pets under 8 weeks and exotic species are not accepted.', '', NULL, 'https://www.aeromexico.com/es_mx/vuelos-con-mascotas', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Aeroméxico', 'Any', 'Pet', 'international', 'AGE MINIMUM', 'Pets must be at least 8 weeks old', 'Aeroméxico does not accept pets younger than 8 weeks.', '', NULL, 'https://www.aeromexico.com/es_mx/vuelos-con-mascotas', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Aeroméxico', 'Any', 'Pet', 'international', 'CARGO', 'Larger pets may travel in the hold with an approved kennel', 'If the pet exceeds cabin weight limits, Aeroméxico offers approved kennel travel in the hold with a current health certificate, vaccination record, and advance reservation.', '', NULL, 'https://www.aeromexico.com/es_mx/vuelos-con-mascotas', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Aeroméxico', 'Any', 'Pet', 'international', 'HEALTH DOCUMENTATION', 'Health certificate and vaccination record required for cabin pets', 'Aeroméxico lists a health certificate and vaccination card among cabin requirements, plus advance reservation.', '', NULL, 'https://www.aeromexico.com/es_mx/vuelos-con-mascotas', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Aeroméxico', 'Any', 'Pet', 'international', 'BREED RESTRICTION', 'Airline does not publish a cabin breed/snub-nose list on its main pets page — ask when reserving', 'Aeroméxico''s public pets FAQ covers weight, carrier, health docs and age but does not list brachycephalic breed bans. Ask when you reserve if your breed has any cabin restrictions.', '', NULL, 'https://www.aeromexico.com/es_mx/vuelos-con-mascotas', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Aeroméxico', 'Any', 'Pet', 'international', 'CONNECTIONS', 'Airline does not publish detailed cabin-pet connection rules — confirm each segment when reserving', 'Confirm pet acceptance and fees on every Aeroméxico segment (and any partner) when you reserve.', '', NULL, 'https://www.aeromexico.com/es_mx/vuelos-con-mascotas', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Aeroméxico', 'Any', 'Pet', 'international', 'DAY OF FLIGHT', 'Arrive early; check-in for pets can take longer', 'Aeroméxico advises arriving early because pet check-in can take longer. Bring the carrier, health certificate and vaccination record.', '', NULL, 'https://www.aeromexico.com/en_mx/flights-with-pets', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Aeroméxico', 'Any', 'Pet', 'international', 'SEAT RESTRICTION', 'Airline does not clearly list exit/bulkhead bans on its main pets page — confirm when reserving', 'Ask Aeroméxico when reserving which seats are allowed with a cabin pet on your aircraft.', '', NULL, 'https://www.aeromexico.com/es_mx/vuelos-con-mascotas', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Aeroméxico', 'Any', 'Pet', 'international', 'LIMITS', 'Space for cabin pets is limited — reserve early', 'Aeroméxico notes you should check availability; cabin pet space is limited by aircraft/route.', '', NULL, 'https://www.aeromexico.com/es_mx/vuelos-con-mascotas', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Aeroméxico', 'Dog', 'Pet', 'international', 'HEALTH DOCUMENTATION', 'Mexico entry: NWS certificate for dogs; SENASICA on arrival', 'Dogs entering Mexico need the New World Screwworm inspection certificate from a USDA-accredited vet (issued ≤5 days before arrival) plus SENASICA arrival checks. Returning to the U.S. with a dog also requires CDC dog importation compliance.', '', NULL, 'https://www.aphis.usda.gov/pet-travel/us-to-another-country-export/pet-travel-us-mexico', '2026-10-15', 'mexico,mex,cun,gdl,sjd,pvr,mty', 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Volaris', 'Any', 'Pet', 'international', 'PET FEE', 'Pet on board: up to $192 USD (low/high season per Volaris ancillaries PDF)', 'Volaris lists “Pet on board” as up to $192 USD in low and high season in its official ancillaries and fees PDF (also payable at airport). Buy when booking, in My Trips, at the counter, or via call center.', '', NULL, 'https://cms.volaris.com/globalassets/pdfs/eng/ancillariesandfees.en.pdf', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Volaris', 'Any', 'Pet', 'international', 'KENNEL REQUIREMENT', 'Onboard carrier max 44×30×19 cm; pet+carrier up to ~26 lb (12 kg on Spanish page)', 'Onboard carrier may be fabric, rigid plastic, or bubble; max 44 cm L × 30 cm W × 19 cm H (17.5 × 12 × 7.5 in). Pet must move inside; English page says up to 26 lb for pet+carrier. Place carrier under the seat ahead of you.', '', NULL, 'https://cms.volaris.com/en/travel-info/optional-services/fly-with-your-pet/', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Volaris', 'Any', 'Pet', 'international', 'BOOKING REQUIREMENT', 'Add “Travel with your pet” when choosing seats, or later in My Trips / call center', 'During booking, at seat selection look for “Travel with your pet” (on board or checked). You can also add it in My Trips, at airport counters, or by calling the Volaris Call Center. Fill the onboard pet form to speed check-in.', '', NULL, 'https://cms.volaris.com/en/travel-info/optional-services/fly-with-your-pet/', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Volaris', 'Any', 'Pet', 'international', 'AGE MINIMUM', 'Minimum age depends on origin/destination (e.g. 8 weeks Mexico routes; 6 months into the U.S.)', 'Volaris publishes minimum ages by origin and destination. Examples: Mexico↔Mexico often 8 weeks; travel involving the United States commonly requires dogs to be 6 months. Check Volaris’ age table for your exact routing.', '', NULL, 'https://cms.volaris.com/en/travel-info/optional-services/fly-with-your-pet/', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Volaris', 'Any', 'Pet', 'international', 'BREED RESTRICTION', 'Brachycephalic and some “dangerous” breeds: waiver or ban — read Volaris lists', 'Volaris recommends against air travel for brachycephalic and certain small breeds and requires a liability waiver at the counter if you still travel with them. Separate “dangerous breeds” (e.g. Pit Bull types, Rottweiler, Doberman, German Shepherd, and others listed on the page) cannot travel onboard or checked.', '', NULL, 'https://cms.volaris.com/en/travel-info/optional-services/fly-with-your-pet/', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Volaris', 'Any', 'Pet', 'international', 'LIMITS', 'One animal per passenger onboard; up to 16 pets per flight (10 dogs / 6 cats)', 'Only one animal per passenger onboard; one animal per container. Capacity up to 16 pets per flight (10 dogs and 6 cats); Bogotá (BOG) limited to 6 pets (3 dogs / 3 cats). Dogs: window seats except premium and exit; cats: last-row window only.', '', NULL, 'https://cms.volaris.com/en/travel-info/optional-services/fly-with-your-pet/', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Volaris', 'Any', 'Pet', 'international', 'CARGO', 'Checked pet option: pet+kennel up to 45 kg (100 lb)', 'Volaris offers checked (documented) pet travel with a rigid kennel; combined weight up to 45 kg (100 lb). Onboard and checked pet services are not available on Frontier-operated flights.', '', NULL, 'https://cms.volaris.com/en/travel-info/optional-services/fly-with-your-pet/', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Volaris', 'Any', 'Pet', 'international', 'HEALTH DOCUMENTATION', 'Vaccination card, pet travel form, health certificate rules by route', 'Domestic Mexico: vaccination booklet (rabies rules apply), deworming ≤6 months, and pet travel form; Animal Health Certificate when required. U.S.–Mexico: NWS/GBG inspection certificate for dogs from USDA-accredited vet ≤5 days before travel (Mexican dogs with proof may be exempt), vaccination record, pet form; CDC Dog Import rules when entering the U.S.', '', NULL, 'https://cms.volaris.com/en/travel-info/optional-services/fly-with-your-pet/', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Volaris', 'Any', 'Pet', 'international', 'DAY OF FLIGHT', 'Counters 2 hours early (domestic) or 3 hours (international)', 'Report to Volaris counters at least 2 hours before domestic and 3 hours before international departures. Present documents, complete the required form, and pay if not prepaid. Airport security may inspect the pet and carrier separately.', '', NULL, 'https://cms.volaris.com/en/travel-info/optional-services/fly-with-your-pet/', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Volaris', 'Any', 'Pet', 'international', 'SEAT RESTRICTION', 'No premium or emergency-exit seats for dogs; cats last-row window only', 'Dogs may travel in any window seat except premium and emergency exit. Cats only in the last-row window. Carrier must go under the seat in front of you.', '', NULL, 'https://cms.volaris.com/en/travel-info/optional-services/fly-with-your-pet/', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Volaris', 'Any', 'Pet', 'international', 'CONNECTIONS', 'Pet service not available on Frontier-operated connecting flights', 'Volaris states onboard and checked pet services are not available for Frontier-operated flights, whether direct or connecting. Confirm pet acceptance on every segment of your itinerary.', '', NULL, 'https://cms.volaris.com/en/travel-info/optional-services/fly-with-your-pet/', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Volaris', 'Dog', 'Service animal', 'international', 'SERVICE ANIMAL', 'Service animals follow Volaris and CDC documentation when entering the U.S.', 'For U.S. entry, dogs must meet CDC rules (including Dog Import Form receipt, microchip, age, and appearance). Follow Volaris’ country-specific document lists on the fly-with-your-pet page.', '', NULL, 'https://cms.volaris.com/en/travel-info/optional-services/fly-with-your-pet/', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Viva Aerobus', 'Any', 'Pet', 'international', 'PET FEE', 'Cabin pet fee: not published as a fixed amount on pages we could verify — confirm when booking', 'Viva’s public fare pages did not return a fixed cabin-pet dollar amount in our official-source check. Confirm the current mascota-en-cabina fee when you add the service in booking or with Viva customer service before you travel.', '', NULL, 'https://www.vivaaerobus.com/es-mx/info/preparate-para-volar/viajando-con-animales/mascotas-en-cabina', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Viva Aerobus', 'Any', 'Pet', 'international', 'KENNEL REQUIREMENT', 'Cabin: soft or rigid carrier; commonly cited max 44×30×19 cm; pet+carrier limits apply', 'Viva requires pets to travel in a ventilated carrier that fits under the seat. Industry/official PDF materials paired with Viva’s pet program use dimensions in the 44×30×19 cm range and a combined weight limit around 10 kg — confirm the exact limits on Viva’s mascotas-en-cabina page when you book.', '', NULL, 'https://www.vivaaerobus.com/es-mx/info/preparate-para-volar/viajando-con-animales/mascotas-en-cabina', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Viva Aerobus', 'Any', 'Pet', 'international', 'BOOKING REQUIREMENT', 'Reserve pet space in advance; sign Viva’s liability letter (carta responsiva) at check-in', 'Advance reservation is required because cabin pet space is limited. At check-in you must sign Viva’s carta responsiva for domestic animals / emotional support / service animals.', '', NULL, 'https://content.vivaaerobus.com/Upload-VB/new-site/ready-to-fly/Carta-responsiva-traslado-de-mascotas.pdf', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Viva Aerobus', 'Any', 'Pet', 'international', 'AGE MINIMUM', 'Minimum age commonly 8 weeks for cabin pets — confirm on Viva’s page for your route', 'Viva’s pet materials and carta responsiva program assume young animals meet airline minimums; confirm the exact minimum age on the official mascotas-en-cabina page for your itinerary.', '', NULL, 'https://www.vivaaerobus.com/es-mx/info/preparate-para-volar/viajando-con-animales/mascotas-en-cabina', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Viva Aerobus', 'Any', 'Pet', 'international', 'HEALTH DOCUMENTATION', 'Vaccination certificate (rabies ≤6 months) and health certificate ≤5 days; carta responsiva', 'Viva’s official carta responsiva requires: (A) vaccination certificate on letterhead with vet license number including rabies (not older than 6 months), (B) health certificate on letterhead issued less than 5 days before travel, plus service/ESAN docs when applicable. Cats must remain in the container at all times.', '', NULL, 'https://content.vivaaerobus.com/Upload-VB/new-site/ready-to-fly/Carta-responsiva-traslado-de-mascotas.pdf', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Viva Aerobus', 'Any', 'Pet', 'international', 'BREED RESTRICTION', 'Airline does not publish a full snub-nose list in the carta responsiva — confirm when booking', 'The verified Viva carta responsiva focuses on documents and behavior, not a full brachycephalic list. Confirm any breed restrictions on Viva’s mascotas-en-cabina page or with customer service before booking.', '', NULL, 'https://content.vivaaerobus.com/Upload-VB/new-site/ready-to-fly/Carta-responsiva-traslado-de-mascotas.pdf', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Viva Aerobus', 'Any', 'Pet', 'international', 'LIMITS', 'Typically one pet per passenger in cabin — confirm capacity when reserving', 'Reserve early; cabin pet capacity is limited. Confirm one-pet-per-passenger and flight caps when you add the service.', '', NULL, 'https://www.vivaaerobus.com/es-mx/info/preparate-para-volar/viajando-con-animales/mascotas-en-cabina', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Viva Aerobus', 'Any', 'Pet', 'international', 'CARGO', 'Ask Viva whether hold/cargo pet transport is offered on your route', 'Confirm with Viva whether documented/hold pet travel is available for your flight; do not assume cargo acceptance without checking the official page for your itinerary.', '', NULL, 'https://www.vivaaerobus.com/es-mx/info/preparate-para-volar/viajando-con-animales/mascotas-en-cabina', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Viva Aerobus', 'Any', 'Pet', 'international', 'DAY OF FLIGHT', 'Check in with documents and signed carta responsiva; pet stays in carrier', 'Bring vaccination and health certificates and complete Viva’s carta responsiva. Keep the pet in the carrier as required (cats must remain inside without exception per the carta).', '', NULL, 'https://content.vivaaerobus.com/Upload-VB/new-site/ready-to-fly/Carta-responsiva-traslado-de-mascotas.pdf', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Viva Aerobus', 'Any', 'Pet', 'international', 'SEAT RESTRICTION', 'Airline does not clearly list exit/bulkhead bans in verified PDF — confirm when booking', 'Ask Viva which seats are allowed with a cabin pet on your aircraft when you reserve.', '', NULL, 'https://www.vivaaerobus.com/es-mx/info/preparate-para-volar/viajando-con-animales/mascotas-en-cabina', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Viva Aerobus', 'Any', 'Pet', 'international', 'CONNECTIONS', 'Confirm pet on every Viva segment; do not assume interline pet transfer', 'Verify pet acceptance on each segment. Do not assume another airline will honor a Viva pet booking without checking that airline.', '', NULL, 'https://www.vivaaerobus.com/es-mx/info/preparate-para-volar/viajando-con-animales/mascotas-en-cabina', '2026-10-15', NULL, 'active');
insert into airline_requirements (airline, animal_type, role, trip_type, category, title, description, deadline_description, submission_link, source_url, verified_at, destination_match, status) values ('Viva Aerobus', 'Dog', 'Pet', 'international', 'HEALTH DOCUMENTATION', 'Mexico/U.S. government rules still apply (NWS, SENASICA, CDC return)', 'Even when flying Viva, dogs entering Mexico need USDA NWS documentation as required by APHIS, SENASICA arrival inspection, and CDC rules when returning to the U.S.', '', NULL, 'https://www.aphis.usda.gov/pet-travel/us-to-another-country-export/pet-travel-us-mexico', '2026-10-15', 'mexico,mex,cun,gdl,sjd,pvr,mty', 'active');
