-- majors mexico complete fills
begin;

delete from airline_requirements where category='CONNECTIONS' and airline in ('Delta','American Airlines','United','Southwest','JetBlue','Alaska Airlines','Frontier','Allegiant','Sun Country');
delete from airline_requirements where airline='Alaska Airlines' and category='SEAT RESTRICTION';
delete from airline_requirements where airline='Sun Country' and category in ('SEAT RESTRICTION','BREED RESTRICTION','DAY OF FLIGHT');
delete from airline_requirements where airline='Frontier' and category='BREED RESTRICTION';
delete from airline_requirements where airline='Frontier' and title='No row one or exit-row seats with a cabin pet';
delete from airline_requirements where airline='Allegiant' and category='BREED RESTRICTION';
delete from airline_requirements where airline='Any' and title in (
  'TSA security: remove pet from carrier; never put the pet through the X-ray',
  'What to pack for airport and cabin pet travel',
  'Pet relief areas: use airport maps; you may need to exit security and re-clear'
);


delete from airline_requirements where airline='Sun Country' and category='PET FEE' and title ilike '%pet fee%';
delete from airline_requirements where airline in ('Aeroméxico','Volaris','Viva Aerobus');

commit;